export function createAudio(){let context,engine,gain,filter,roadGain,sirens=[],noiseBuffer,enabled=false,userSet=false;
 function ensure(){if(context)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;context=new AC();engine=context.createOscillator();engine.type='sawtooth';filter=context.createBiquadFilter();filter.type='lowpass';gain=context.createGain();gain.gain.value=0;engine.connect(filter).connect(gain).connect(context.destination);engine.start();noiseBuffer=context.createBuffer(1,context.sampleRate*2,context.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1);const noise=context.createBufferSource();noise.buffer=noiseBuffer;noise.loop=true;const low=context.createBiquadFilter();low.type='lowpass';low.frequency.value=650;roadGain=context.createGain();roadGain.gain.value=0;noise.connect(low).connect(roadGain).connect(context.destination);noise.start();for(let i=0;i<2;i++){const osc=context.createOscillator(),g=context.createGain();osc.type='sine';g.gain.value=0;osc.connect(g).connect(context.destination);osc.start();sirens.push({osc,g});}}
 function noiseBurst(level,duration,frequency){if(!context||!enabled)return;const source=context.createBufferSource(),f=context.createBiquadFilter(),g=context.createGain(),t=context.currentTime;source.buffer=noiseBuffer;f.type='lowpass';f.frequency.setValueAtTime(frequency,t);f.frequency.exponentialRampToValueAtTime(100,t+duration);g.gain.setValueAtTime(level,t);g.gain.exponentialRampToValueAtTime(.0001,t+duration);source.connect(f).connect(g).connect(context.destination);source.start();source.stop(t+duration);source.onended=()=>{source.disconnect();f.disconnect();g.disconnect();};}
 function tone(frequency,end,level,duration,type='sine'){if(!context||!enabled)return;const o=context.createOscillator(),g=context.createGain(),t=context.currentTime;o.type=type;o.frequency.setValueAtTime(frequency,t);o.frequency.exponentialRampToValueAtTime(end,t+duration);g.gain.setValueAtTime(level,t);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g).connect(context.destination);o.start();o.stop(t+duration);o.onended=()=>{o.disconnect();g.disconnect();};}
 return {get enabled(){return enabled;},async start(){ensure();if(!context)return false;if(!userSet)enabled=true;await context.resume();return enabled;},async toggle(){ensure();if(!context)return false;userSet=true;enabled=!enabled;await context.resume();if(!enabled)window.speechSynthesis?.cancel();return enabled;},
 update(state,paused,cues={}){if(!context)return;const t=context.currentTime;for(let i=0;i<sirens.length;i++){const {osc,g}=sirens[i];osc.frequency.setTargetAtTime(i?(Math.floor(t*1.7)%2?770:960):650+300*Math.sin(t*4),t,.04);g.gain.setTargetAtTime(enabled&&!paused?(i?cues.ambulance||0:cues.police||0)*.035:0,t,.1);}engine.frequency.setTargetAtTime(state.flight?100+state.throttle*65:26+state.rpm/65,t,.08);filter.frequency.setTargetAtTime(140+state.throttle*450,t,.1);gain.gain.setTargetAtTime(enabled&&!paused?.012+state.throttle*.023:0,t,.1);roadGain.gain.setTargetAtTime(enabled&&!paused&&!state.flight?Math.min(.035,Math.abs(state.speed)*.0015):0,t,.15);},
 click(){tone(800,750,.025,.045);},impact(speed){const level=Math.min(.32,.08+speed*.018);noiseBurst(level,.3,2200);tone(145,38,level*.7,.36);tone(620,170,level*.15,.18,'triangle');},explosion(distance=25){const level=Math.min(1,35/Math.max(12,distance));noiseBurst(.35*level,1.8,3200);tone(110,23,.28*level,1.4);tone(52,30,.15*level,1.9);},launch(){noiseBurst(.17,.65,6500);tone(220,1000,.05,.34,'triangle');},radio(){tone(1100,1100,.035,.11);},speak(text){if(!enabled||!window.speechSynthesis)return;window.speechSynthesis.cancel();const phrase=new SpeechSynthesisUtterance(text);phrase.lang='ja-JP';phrase.rate=1.02;phrase.volume=.75;const voice=window.speechSynthesis.getVoices().find(v=>v.lang.startsWith('ja'));if(voice)phrase.voice=voice;window.speechSynthesis.speak(phrase);},stopSpeech(){window.speechSynthesis?.cancel();}};
}
